var t=`1360-arepas-con-queso`;var i=`world-1360`;var n=`CO`;var a=`south-america`;var s=4;var r=51;var u={en:`Arepas con Queso`,ua:`Арепас із сиром`};var l={en:`Arepas con Queso is a dish from Colombia featuring arepa flour, queso fresco, mozzarella, avocado. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Арепас із сиром, страва кухні країни Колумбія з такими основними складниками: борошно для ареп, кесо фреско, моцарела, авокадо. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Mix the corn flour with the measured water and salt until a soft cohesive, non-sticky masa forms. Rest covered for about 10 minutes; this gluten-free dough does not become elastic like wheat dough.`,ua:`Змішайте кукурудзяне борошно із зазначеною водою й сіллю до м’якої цілісної маси, що не липне. Накрийте на приблизно 10 хвилин; таке безглютенове тісто не стає еластичним, як пшеничне.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`arepa-flour`,470,`g`],[`water`,580,`ml`],[`table-salt`,8,`g`],[`unsalted-butter`,45,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:11,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 17 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 17 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:17,i:[[`canola-oil`,65,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:6,i:[[`queso-fresco`,250,`g`],[`mozzarella`,180,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`avocado`,2,`pcs`]]}];var d={slug:t,id:i,country:`CO`,region:a,servings:4,minutes:51,title:u,text:l,steps:h};export{n as country,d as default,i as id,r as minutes,a as region,s as servings,t as slug,h as steps,l as text,u as title};